import sys
from heapq import heappop, heappush

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n, m = int(input[ptr]), int(input[ptr+1])
    ptr += 2
    edges = []
    for _ in range(m):
        a, b, e = int(input[ptr]), int(input[ptr+1]), int(input[ptr+2])
        edges.append((e, a-1, b-1))
        ptr += 3
    edges.sort()

    parent = list(range(n))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return False
        parent[v_root] = u_root
        return True

    mst_edges = []
    for e, a, b in edges:
        if union(a, b):
            mst_edges.append((e, a, b))

    mst_set = set()
    for e, a, b in mst_edges:
        mst_set.add((min(a, b), max(a, b)))

    res = []
    for idx, (e, a, b) in enumerate(edges):
        if (min(a, b), max(a, b)) not in mst_set:
            a_root = find(a)
            b_root = find(b)
            parent[a_root] = b_root
            new_mst_edges = []
            for ee, aa, bb in edges:
                if union(aa, bb):
                    new_mst_edges.append((ee, aa, bb))
            parent = list(range(n))
            max_e = 0
            for ee, aa, bb in new_mst_edges:
                if ee > max_e:
                    max_e = ee
            res.append(max_e)
            parent = list(range(n))
            for ee, aa, bb in mst_edges:
                union(aa, bb)

    for num in res:
        print(num)

